package com.ptms.controller; import com.ptms.dto.*; import com.ptms.service.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/visitors") public class VisitorController{private final VisitorService s;public VisitorController(VisitorService s){this.s=s;}@GetMapping public List<VisitorDto>all(){return s.all();}@PostMapping public VisitorDto save(@Valid @RequestBody VisitorDto d){return s.save(d);}@PutMapping("/{id}") public VisitorDto update(@PathVariable Long id,@Valid @RequestBody VisitorDto d){return s.save(new VisitorDto(id,d.visitorCode(),d.name(),d.nic(),d.vehicleNumber(),d.hostDepartment()));}}
